import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { signalsFeaturesList } from 'products/signals/frontend/generated/api'
import type { InboxFeatureReportApi } from 'products/signals/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureListLogicValues {
    currentProjectId: number | string // teamLogic
    features: InboxFeatureReportApi[]
    featuresLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureListLogicActions {
    loadFeatures: () => any
    loadFeaturesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadFeaturesSuccess: (
        features: InboxFeatureReportApi[],
        payload?: any
    ) => {
        features: InboxFeatureReportApi[]
        payload?: any
    }
}

export type featureListLogicType = MakeLogicType<featureListLogicValues, featureListLogicActions>

/**
 * Loads long-lived feature reports for the Features tab. Creation starts the feature's planning phase.
 */
export const featureListLogic = kea<featureListLogicType>([
    path(['scenes', 'inbox', 'logics', 'featureListLogic']),

    connect(() => ({
        values: [teamLogic, ['currentProjectId']],
    })),

    loaders(({ values }) => ({
        features: [
            [] as InboxFeatureReportApi[],
            {
                loadFeatures: async () => {
                    const response = await signalsFeaturesList(String(values.currentProjectId))
                    return response.results
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadFeatures()
    }),
])
